{
  "status": "SUPPORTED",
  "task_summary": "Find fastening components and tool, assemble workpiece, and leave tool on bench.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "Fastener",
        "entity_kind": "OBJECT",
        "function": "Join or secure other objects",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["screw", "bolt", "nut", "clip", "pin"],
        "required_properties": ["fits_into_workpiece_hole", "holds_workpiece_in_place"]
      },
      {
        "id": "Workpiece",
        "entity_kind": "OBJECT",
        "function": "Object to be joined or secured",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["assembly", "device", "block", "component"],
        "required_properties": ["has_fastening_point", "can_be_secured"]
      },
      {
        "id": "Fastening Tool",
        "entity_kind": "OBJECT",
        "function": "Implement used to apply the fastener",
        "required_count": 1,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["screwdriver", "wrench", "pliers", "hand_tool"],
        "required_properties": ["manipulates_fastener", "safe_to_leave_on_bench"]
      },
      {
        "id": "Workbench Surface",
        "entity_kind": "REGION",
        "function": "Support surface for the tool after use",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["table", "bench", "work_surface"],
        "required_properties": ["flat", "stable", "accessible"]
      }
    ],
    "functional_relations": [
      {
        "id": "FastenerSecuresWorkpiece",
        "relation": "connects_to",
        "participant_roles": ["Fastener", "Workpiece"],
        "required": true
      },
      {
        "id": "ToolAppliesFastener",
        "relation": "operates_on",
        "participant_roles": ["Fastening Tool", "Fastener", "Workpiece"],
        "required": true
      },
      {
        "id": "ToolRestsOnSurface",
        "relation": "rests_on",
        "participant_roles": ["Fastening Tool", "Workbench Surface"],
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "LocateComponents",
        "operation": "search_and_identify",
        "participant_roles": ["Fastener", "Fastening Tool"],
        "operation_count": 1
      },
      {
        "id": "PerformFastening",
        "operation": "apply_fastener",
        "participant_roles": ["Fastening Tool", "Fastener", "Workpiece"],
        "operation_count": 1
      },
      {
        "id": "DepositTool",
        "operation": "place_object",
        "participant_roles": ["Fastening Tool", "Workbench Surface"],
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "Fastener": [],
      "Workpiece": [
        { "label": "Yellow rectangular object", "visual_description": "Yellow block-like item sitting on a blue tray/mat on the table" }
      ],
      "Fastening Tool": [],
      "Workbench Surface": [
        { "label": "Wooden table top", "visual_description": "Flat wooden surface with a blue tray and yellow object on it" }
      ]
    },
    "inspectable_regions": [
      {
        "id": "LeftDrawer",
        "label": "Left Drawer",
        "visual_description": "Blue drawer under the left side of the table, handle visible",
        "reason": "Closed storage structure, likely contains tools or spare components"
      },
      {
        "id": "RightDrawer",
        "label": "Right Drawer",
        "visual_description": "Blue drawer under the right side of the table, handle visible",
        "reason": "Closed storage structure, likely contains tools or spare components"
      },
      {
        "id": "Cabinet",
        "label": "Cabinet",
        "visual_description": "Tall blue cabinet standing behind the table, door closed",
        "reason": "Closed storage structure, likely contains tools or components"
      }
    ],
    "inspection_order": [
      "LeftDrawer",
      "RightDrawer",
      "Cabinet"
    ]
  }
  ,
  "unsupported_reason": ""
  ,
  "schema_version": 3
}
